class TweetCounts {
    unordered_map<string, map<int,int>> data;
public:
    TweetCounts() {

    }

    void recordTweet(string tweetName, int time) {
        data[tweetName][time]++;
    }

    vector<int> getTweetCountsPerFrequency(string freq, string tweetName, int startTime, int endTime) {
        int chunk;
        if (freq == "minute") chunk = 60;
        else if (freq == "hour") chunk = 3600;
        else chunk = 86400;

        int numChunks = (endTime - startTime) / chunk + 1;
        vector<int> result(numChunks, 0);

        auto it = data.find(tweetName);
        if (it == data.end()) return result;

        map<int,int>& times = it->second;
        auto pos = times.lower_bound(startTime);
        while (pos != times.end() && pos->first <= endTime) {
            int idx = (pos->first - startTime) / chunk;
            result[idx] += pos->second;
            ++pos;
        }
        return result;
    }
};
